from rich.console import Console
import sys
import io

class Proxy:
    def __init__(self, wrapped):
        self._wrapped = wrapped

    def __getattr__(self, name):
        return getattr(self._wrapped, name)

    def write(self, data):
        self._wrapped.write(data)

    def flush(self):
        self._wrapped.flush()

def test_proxy_isatty():
    # Use sys.stdout which is usually a TTY in a real terminal, 
    # but in this environment it might not be.
    # Let's mock a file that has isatty() returning True.
    class MockFile:
        def isatty(self):
            return True
        def write(self, data):
            pass
        def flush(self):
            pass

    mock_file = MockFile()
    proxy_file = Proxy(mock_file)

    console = Console(file=proxy_file)
    print(f"Is terminal: {console.is_terminal}")
    assert console.is_terminal is True

if __name__ == "__main__":
    try:
        test_proxy_isatty()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        sys.exit(1)
